for name in names:
    print(name)

for i in range(1, 6):
    if i == 3:
        break
    print(i)

for i in range(1, 6):
    if i == 3:
        continue
    print(i)

for i in range(3):
    pass

print("Loop completed")

for i in range(1, 3):
    for j in range(1, 3):
        print(i, j)

for i in range(1, 4):
    for j in range(1, 4):
        if j == 2:
            break
        print(i, j)

for i in range(1, 6):
    if i == 3:
        continue
    print(i)

for i in range(3):
    print(i)
else:
    print("Loop completed normally")

for i in range(5):
    if i == 2:
        break
    print(i)
else:
    print("Loop completed normally")
